/* input effects */
.effCont {
  position: relative;
}

.eff_1 + span {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0%;
  height: 2px;
  background-color: rgb(66, 119, 233);
  transition: 500ms ease-in;
}
.eff_1:focus + span {
  width: 100%;
  transition: 500ms ease-out;
}
.eff_2 + span {
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 0%;
  height: 2px;
  background-color: rgb(66, 119, 233);
  transition: 500ms ease-in;
}
.eff_2:focus + span {
  width: 100%;
  transition: 500ms ease-out;
  left: 0;
}
.eff_3 + span {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 2px;
  z-index: 99;
}
.eff_3 + span:before, .eff_3 + span:after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 100%;
  background-color: rgb(66, 119, 233);
  transition: 500ms ease-in;
}
.eff_3 + span:after {
  left: auto;
  right: 0;
  transition: 500ms ease-in;
}
.eff_3:focus + span:before, .eff_3:focus + span:after {
  content: "";
  width: 50%;
  transition: 500ms ease-out;
}

