  font-size: 1rem;
  text-decoration: none;
  list-style: none;
  color: #383838;
}

.tb-S-slideL {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.5rem;
  position: absolute;
  z-index: 9;
  height: auto;
  max-height: 400px;
  overflow-y: auto;
  left: -2000px;
  width: 300px;
  bottom: calc(20px + 2rem);
  transition: 300ms ease-out;
}
@media only screen and (max-width: 479px) {
  .tb-S-slideL {
    width: calc(100vw - 1rem);
  }
}

.tb_sliderL:hover .tb-S-slideL {
  left: 0px;
  transition: 300ms ease-in;
}

.tb_middle {
  background-color: #dddccc;
  overflow-x: auto;
  overflow-y: hidden;
  overscroll-behavior-inline: contain;
  display: flex;
  flex-direction: row;
}
.tb_middle > a {
  padding: 1rem;
  text-decoration: none;
  list-style: none;
  color: #383838;
  justify-self: center;
  align-self: center;
}

.tb_sliderR {
  padding: 1rem;
  position: relative;
  background-color: #dddccc;
}
.tb_sliderR > a {
  display: grid;
  font-size: 24px;
  text-decoration: none;
  list-style: none;
  justify-self: center;
  align-self: center;
  color: #383838;
}
.tb_sliderR > div {
  padding: 1rem;
  background-color: #ccc;
  text-decoration: none;
  list-style: none;
  color: #383838;
}
@media only screen and (max-width: 767px) {
  .tb_sliderR > div {
    padding: 0.5rem;
  }
}
.tb_sliderR > div > a {
  display: grid;
  font-size: 1rem;
  text-decoration: none;
  list-style: none;
  color: #383838;
  text-align: right;
}

.tb-S-slideR {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.5rem;
  position: absolute;
  z-index: 9;
  height: auto;
  max-height: 400px;
  overflow-y: auto;
  right: -2000px;
  width: 300px;
  bottom: calc(20px + 2rem);
  transition: 300ms ease-out;
}
@media only screen and (max-width: 479px) {
  .tb-S-slideR {
    width: calc(100vw - 1rem);
  }
}

.tb_sliderR:hover .tb-S-slideR {
  right: 0px;
  transition: 300ms ease-in;
}

