/* Responsiveness */
/* Responsiveness */
/***********************************************************************************/
/***********************************************************************************/
/********************************** DESKTOP ****************************************/
/***********************************************************************************/
/***********************************************************************************/
@media screen and (max-width: 991px) {
  /* start of large tablet styles */
}
/***********************************************************************************/
/***********************************************************************************/
/*********************************** TABLET ****************************************/
/***********************************************************************************/
/***********************************************************************************/
@media screen and (max-width: 767px) {
  /* start of medium tablet styles */
  body {
    font-size: 12px;
  }
  .resTable {
    display: grid;
    border: 0px;
  }
  .resHeaderItem {
    display: none;
  }
  .resRow {
    display: grid;
    margin-bottom: 16px;
  }
  .resRow:nth-child(odd) {
    background-color: #fff;
  }
  .resRow:nth-child(even) {
    background-color: #fff;
  }
  .resData {
    text-align: right;
    padding: 4px;
    color: #3b3838;
    position: relative;
    border-bottom: 2px solid #fff;
    width: 100%;
  }
  .resData:nth-child(odd) {
    background-color: #dddfff;
  }
  .resData:nth-child(even) {
    background-color: #eeefff;
  }
  .resData:before {
    content: attr(data-label);
    position: absolute;
    left: 0;
    width: 40%;
    text-align: left;
    padding: 0px 4px;
    color: #3b3838;
    font-weight: bold;
  }
}
/***********************************************************************************/
/***********************************************************************************/
/************************************* MOBILE **************************************/
/***********************************************************************************/
/***********************************************************************************/
@media screen and (max-width: 479px) {
  /* start of phone styles */
  body {
    font-size: 11px;
  }
  .titleR {
    font-size: 1.1rem;
  }
  .titleL {
    font-size: 1.1rem;
  }
  .titleC {
    font-size: 1.1rem;
  }
  .subTitleR {
    font-size: 0.8rem;
  }
  .subTitleL {
    font-size: 0.8rem;
  }
  .subTitleC {
    font-size: 0.8rem;
  }
}
